initial_condition:
with {
    the SUT containing a core context and it has been deleted with reload set to true.
                }

test_cases.then:
then {
    the SUT sends a valid Response for the operation:
        Serve a @context with Response Status Code set to 200
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/jsonldContexts/{contextId}'
        method set to 'GET'
        Serve a @context with contextID 'https://uri.etsi.org/ngsi-ld/v1/ngsi-ld-core-context-v1.6.jsonld' and details 'true'
}
